function fundir(ant, nov) {
  const out = Object.assign({}, ant || {});
  for (const [k, v] of Object.entries(nov || {})) {
    if (v === null || v === undefined) continue;
    if (typeof v === 'string' && v.trim() === '') continue;
    if (Array.isArray(v)) { if (v.length) out[k] = v; continue; }
    if (typeof v === 'object') { out[k] = fundir(out[k], v); continue; }
    out[k] = v;
  }
  return out;
}

