//
// IMPORTANTE na v4: dia_combinado SEMPRE sai no JSON (data ou
// null). Diferente do tema_audio, aqui queremos que uma mensagem
// nova SEM dia combinado LIMPE o valor antigo no upsert — se a
// conversa retomou, o compromisso anterior deixa de valer.
//
// Mantido da v3: se o Adaptar Entrada Z-API detectou anúncio de
// laser/avaliação (body._anuncio_tema), grava tema_audio — e SÓ
// quando detectado, para o merge-duplicates preservar o valor.
// ============================================================
const TZ = 'America/New_York';

const op = $("Normalizar Dados Operacionais").first().json;
const body = op.lexia_body_normalizado || {};

// Instagram e WhatsApp; nunca em modo teste.
const CANAIS_VALIDOS = ['instagram','whatsapp','messenger'];

