const agora = $now.setZone(TZ);

// Encontra o próximo momento dentro da janela comercial (7h–20h, seg–sáb).
function proximaJanelaValida(dt) {
  let t = dt;
  for (let i = 0; i < 14; i++) {
    if (t.weekday === 7) { // domingo
      t = t.plus({ days: 1 }).set({ hour: 7, minute: 0, second: 0, millisecond: 0 });
      continue;
    }
    if (t.hour < 7) {
      t = t.set({ hour: 7, minute: 0, second: 0, millisecond: 0 });
      continue;
    }
    if (t.hour >= 20) {
      t = t.plus({ days: 1 }).set({ hour: 7, minute: 0, second: 0, millisecond: 0 });
      continue;
    }
    return t;
  }
  return t;
}

// ============================================================
// DIA COMBINADO — determinístico, nada de IA.
// Detecta quando o cliente combinou um DIA para ser contactado:
// "te falo na quinta", "pode ser sexta", "I'll let you know on
// Monday", "te hablo el jueves", "me chama semana que vem",
// "te confirmo dia 15"...
// Devolve um DateTime (o dia) ou null.
// NÃO confunde com agendamento de sessão: frases com "agendar",
// "marcar", "tem horário", "book", ou com horário específico
// ("quinta às 3") são ignoradas — isso é papo de agenda, não
// promessa de retorno.
// ============================================================
function extrairDiaCombinado(texto) {
  const t = ' ' + String(texto || '').toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ').trim() + ' ';
  if (t.trim() === '') return null;

  // Parece conversa de AGENDAMENTO (escolher horário de sessão)? Não é dia combinado.
  if (/\b(agendar|marcar|appointment|book|schedule|cita|encaixe|disponibilidade|tem horario|que horas|what time|a que hora)\b/.test(t)) return null;
  if (/\b(as|at|a las?) ?\d{1,2}([:h]\d{2})? ?(am|pm|h)?\b/.test(t)) return null;

  const temIntencaoContato =
    /\b(te falo|te aviso|te respondo|te confirmo|te retorno|entro em contato|eu (te )?chamo|me chama|me liga|me manda (mensagem|msg)|falamos|conversamos|pode ser|pode me chamar|i'?ll (let you know|text( you)?|reach out|get back|message you|contact you)|(text|message|contact) me( on| next)?|let'?s talk|te hablo|les? aviso|te escribo|hablamos|escribeme|me escribes|puede ser)\b/.test(t);
  const mensagemCurta = t.trim().length <= 45;
  if (!temIntencaoContato && !mensagemCurta) return null;

  if (/\b(depois de amanha|day after tomorrow|pasado manana)\b/.test(t)) return agora.plus({ days: 2 });
  if (/\b(amanha|tomorrow)\b/.test(t)) return agora.plus({ days: 1 });
  if (/\bmanana\b/.test(t) && !/\b(la|de|por|esta) manana\b/.test(t)) return agora.plus({ days: 1 });

  if (/\b(semana que vem|proxima semana|semana seguinte|next week|la semana que viene|la proxima semana)\b/.test(t)) return agora.plus({ days: 7 });

  if (/\b(fim de semana|final de semana|weekend|fin de semana)\b/.test(t)) {
    let alvoFds = agora.plus({ days: 1 });
    while (alvoFds.weekday !== 6) alvoFds = alvoFds.plus({ days: 1 });
    return alvoFds;
  }

  const DIAS = [
    [/\b(segunda(?:[ -]feira)?|monday|lunes)\b/, 1],
    [/\b(terca(?:[ -]feira)?|tuesday|martes)\b/, 2],
    [/\b(quarta(?:[ -]feira)?|wednesday|miercoles)\b/, 3],
    [/\b(quinta(?:[ -]feira)?|thursday|jueves)\b/, 4],
    [/\b(sexta(?:[ -]feira)?|friday|viernes)\b/, 5],
    [/\b(sabado|saturday)\b/, 6],
    [/\b(domingo|sunday)\b/, 7]
  ];
  for (const [re, wd] of DIAS) {
    if (re.test(t)) {
      let delta = (wd - agora.weekday + 7) % 7;
      if (delta === 0) delta = 7; // mesmo dia da semana → próxima ocorrência
      return agora.plus({ days: delta });
    }
  }

  const m = t.match(/\b(?:dia|el|the) (\d{1,2})(?:st|nd|rd|th)?\b/);
  if (m) {
    const diaMes = Number(m[1]);
    if (diaMes >= 1 && diaMes <= 31) {
      let alvoMes = agora.set({ day: Math.min(diaMes, agora.daysInMonth) });
      if (alvoMes <= agora) {
        const prox = agora.plus({ months: 1 });
        alvoMes = prox.set({ day: Math.min(diaMes, prox.daysInMonth) });
      }
      return alvoMes;
    }
  }
  return null;
}

// ============================================================
// TEMPO PEDIDO PELO CLIENTE — determinístico, nada de IA.
// Só considera o tempo se a frase tiver INTENÇÃO de espera
// ("give me", "daqui a", "dame", "let me"...), para não
// confundir com perguntas tipo "a sessão dura 30 minutos?".
// Devolve minutos (número) ou null.
// ============================================================
function extrairMinutosPedidos(texto) {
  const t = ' ' + String(texto || '').toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ').trim() + ' ';
  if (t.trim() === '') return null;

  const temIntencao =
    /\b(give me|gimme|get back|let me|hold on|hang on|hold tight|in about|in like|me da|so me da|daqui a|daqui uns|em uns|te falo|te aviso|te respondo|ja te|volto em|dame|en unos|en un rato|te aviso en|te hablo en|regreso en|vuelvo en|minutinho|minutinhos|horinha)\b/.test(t) ||
    /\b(in|em|en) \d{1,3} ?(ish )?(min|mins|minutes|minutos|minuto|h|hr|hrs|hour|hours|hora|horas)\b/.test(t);
  if (!temIntencao) return null;

  // "meia hora" / "half an hour" / "media hora"
  if (/\b(meia hora|half an hour|half hour|media hora)\b/.test(t)) return 30;
  // "uma hora" / "an hour" / "one hour" / "una hora"
  if (/\b(uma hora|an hour|one hour|una hora|1 hora|1 hour)\b/.test(t)) return 60;

  // "X min", "X ish minutes", "30ish min"
  let m = t.match(/\b(\d{1,3}) ?-? ?(?:ish ?)?(?:min|mins|minutes|minutos|minuto)\b/);
  if (m) return Number(m[1]);

  // "X horas", "X hours", "2h"
  m = t.match(/\b(\d{1,2}) ?-? ?(?:ish ?)?(?:h|hr|hrs|hour|hours|hora|horas)\b/);
  if (m) return Number(m[1]) * 60;

  return null;
}

