SELECT coalesce(jsonb_agg(to_jsonb(s)||jsonb_build_object('account_status',a.status,'provider',a.provider,'provider_account_ref',a.provider_account_ref)),'[]'::jsonb) AS states
FROM public.lexia_conversation_states s JOIN public.lexia_channel_accounts a ON a.id=s.account_id
WHERE s.environment=$1 AND s.cliente_slug=$2 AND s.channel=$3 AND s.account_id=$4::uuid AND s.conversation_ref=$5;

WITH proposed AS (SELECT coalesce(jsonb_agg(jsonb_build_object('action_id',(substr(md5(jsonb_build_array($2::text,e.n)::text),1,8)||'-'||substr(md5(jsonb_build_array($2::text,e.n)::text),9,4)||'-4'||substr(md5(jsonb_build_array($2::text,e.n)::text),14,3)||'-8'||substr(md5(jsonb_build_array($2::text,e.n)::text),18,3)||'-'||substr(md5(jsonb_build_array($2::text,e.n)::text),21,12))::uuid,'sequence',e.n,'content',jsonb_build_object('type','text','text',e.v->>'texto')) ORDER BY e.n),'[]'::jsonb) AS actions FROM jsonb_array_elements($1::jsonb) WITH ORDINALITY e(v,n)), planned AS (
SELECT public.lexia_migration_reply_plan($3::uuid,$2::uuid,proposed.actions,$4::bigint,$5::bigint) AS plan FROM proposed)
SELECT plan->'actions' AS actions,plan->'captured_state' AS captured_state,plan->>'kind' AS kind,plan->>'source_ref' AS source_ref FROM planned;

